"""Barcode = gap sequence: extract the finite H_0 barcode from the primes."""
from __future__ import annotations
from collections import Counter
from typing import Dict, List


def sieve_primes(bound: int) -> List[int]:
    if bound < 2:
        return []
    sieve = bytearray([1]) * (bound + 1)
    sieve[0] = sieve[1] = 0
    for i in range(2, int(bound ** 0.5) + 1):
        if sieve[i]:
            sieve[i * i:bound + 1:i] = b"\x00" * len(range(i * i, bound + 1, i))
    return [i for i in range(2, bound + 1) if sieve[i]]


def h0_barcode(primes: List[int]) -> List[int]:
    """The i-th finite H_0 bar has death scale p_{i+1} - p_i (the i-th gap)."""
    return [primes[i + 1] - primes[i] for i in range(len(primes) - 1)]


def histogram(barcode: List[int]) -> Dict[int, int]:
    return dict(sorted(Counter(barcode).items()))


if __name__ == "__main__":
    primes = sieve_primes(100)
    bc = h0_barcode(primes)
    print("primes:", primes)
    print("barcode (bar lengths):", bc)
    print("multiplicities:", histogram(bc))

"""Single-Linkage Theorem: closed-form component count vs. union-find."""
from __future__ import annotations
from typing import List


def sieve_primes(bound: int) -> List[int]:
    sieve = bytearray([1]) * (bound + 1)
    sieve[0] = sieve[1] = 0
    for i in range(2, int(bound ** 0.5) + 1):
        if sieve[i]:
            sieve[i * i:bound + 1:i] = b"\x00" * len(range(i * i, bound + 1, i))
    return [i for i in range(2, bound + 1) if sieve[i]]


def components_formula(positions: List[int], eps: float) -> int:
    """#components = #(gaps > eps) + 1  (Single-Linkage Theorem)."""
    gaps = [positions[i + 1] - positions[i] for i in range(len(positions) - 1)]
    return sum(1 for g in gaps if g > eps) + 1


def components_unionfind(positions: List[int], eps: float) -> int:
    parent = list(range(len(positions)))

    def find(x: int) -> int:
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    for i in range(len(positions) - 1):
        if positions[i + 1] - positions[i] <= eps:
            ra, rb = find(i), find(i + 1)
            parent[ra] = rb
    return len({find(i) for i in range(len(positions))})


if __name__ == "__main__":
    primes = sieve_primes(500)
    for eps in [1, 2, 4, 6, 10, 20]:
        f = components_formula(primes, eps)
        u = components_unionfind(primes, eps)
        print(f"eps={eps:3d}: formula={f:4d} union-find={u:4d} match={f == u}")

"""The average-gap law: mean bar length ~ log(x) by telescoping and PNT."""
from __future__ import annotations
import math
from typing import List


def sieve_primes(bound: int) -> List[int]:
    sieve = bytearray([1]) * (bound + 1)
    sieve[0] = sieve[1] = 0
    for i in range(2, int(bound ** 0.5) + 1):
        if sieve[i]:
            sieve[i * i:bound + 1:i] = b"\x00" * len(range(i * i, bound + 1, i))
    return [i for i in range(2, bound + 1) if sieve[i]]


def mean_bar_length(primes: List[int]) -> float:
    """(p_N - p_0)/N: telescoping sum of gaps divided by their count."""
    return (primes[-1] - primes[0]) / (len(primes) - 1)


if __name__ == "__main__":
    primes = sieve_primes(1_000_000)
    for b in [1_000, 10_000, 100_000, 1_000_000]:
        sub = [p for p in primes if p <= b]
        print(f"x={sub[-1]:>8}  mean bar={mean_bar_length(sub):7.4f}  "
              f"log(x)={math.log(sub[-1]):7.4f}")

